// Des: Tests for ru-chat-acts on the sim: react, quote-reply, recall, delete, pin message, download, archive, hide, unread, alias, block, sticker
// Flo: sim chat > run each action > read page state; failure cases: missing message, no force, dry
// I/O: sim page > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const acts = @import("ru-chat-acts.zig"); const snd = @import("ru-chat-send.zig"); const rig = @import("te-rigz-main.zig"); const T = std.testing;
test "react to a message picks the emoji after hovering it" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); try T.expect(try acts.doAct(&ses, .react, "Mom", "Dinner at 7", "👍")); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.reacts.length")); try T.expect(std.mem.endsWith(u8, try rg.js("Z.st.reacts[0]"), ":👍")); }
test "quote-reply sends the text with the quoted message attached" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); try T.expect(try acts.doAct(&ses, .quote, "Mom", "Dinner at 7", "yes, 7 is fine")); try T.expectEqualStrings("Mom|yes, 7 is fine", try rg.js("Z.st.sent[0]")); try T.expectEqualStrings("Dinner at 7?", try rg.js("Z.chats[0].msgs[Z.chats[0].msgs.length-1].quote")); }
test "recall own message needs force, then recalls it; the other side's message has no recall button" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var live = rg.ses(rig.cfgOf(), .live); _ = try snd.sendText(&live, "Mom", "oops wrong chat"); try T.expectError(error.NeedForce, acts.doAct(&live, .recall, "Mom", "oops wrong", "")); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.recalled.length")); var frc = rg.ses(rig.cfgOf(), .force); frc.fake_ms += 600000; try T.expect(try acts.doAct(&frc, .recall, "Mom", "oops wrong", "")); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.recalled.length")); frc.fake_ms += 600000; try T.expectError(error.NoElem, acts.doAct(&frc, .recall, "Mom", "Dinner at 7", "")); }
test "delete for me removes the message after force" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var frc = rg.ses(rig.cfgOf(), .force); try T.expect(try acts.doAct(&frc, .delme, "Mom", "Hi son", "")); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.deleted.length")); try T.expectEqual(@as(i64, 1), try rg.num("Z.chats[0].msgs.length")); }
test "pin message and chat-level buttons: archive, hide, unread, alias" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); try T.expect(try acts.doAct(&ses, .pinm, "Boss", "Report ready", "")); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.pinmsg.length")); try T.expect(try acts.doAct(&ses, .unre, "Boss", "", "")); try T.expectEqualStrings("Boss", try rg.js("Z.st.unr[0]")); try T.expect(try acts.doAct(&ses, .alia, "Boss", "", "")); try T.expectEqualStrings("alias", try rg.js("Z.st.alias.Boss")); try T.expect(try acts.doAct(&ses, .hide, "Boss", "", "")); try T.expectEqualStrings("Boss", try rg.js("Z.st.hid[0]")); try T.expect(try acts.doAct(&ses, .arch, "Anna#group", "", "")); try T.expectEqualStrings("Anna", try rg.js("Z.st.arch[0]")); }
test "block needs force; stickers pick by name" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var live = rg.ses(rig.cfgOf(), .live); try T.expectError(error.NeedForce, acts.doAct(&live, .bloc, "Boss", "", "")); try T.expect(try acts.doAct(&live, .stic, "Mom", "", "Cười")); try T.expectEqualStrings("Cười", try rg.js("Z.st.stickers[0]")); var frc = rg.ses(rig.cfgOf(), .force); frc.fake_ms += 600000; try T.expect(try acts.doAct(&frc, .bloc, "Boss", "", "")); try T.expectEqualStrings("Boss", try rg.js("Z.st.blocked[0]")); }
test "dry run previews with a hashed body and changes nothing; read-only and bad input" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var dry = rg.ses(rig.cfgOf(), .dry); try T.expect(!try acts.doAct(&dry, .react, "Mom", "Dinner at 7", "👍")); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.reacts.length")); const rows = try rg.sto.logTail(rg.aren.allocator(), 2); try T.expect(std.mem.startsWith(u8, rows[rows.len - 1].msg, "PREVIEW react Mom «h:")); var rdo = rg.ses(rig.cfgOf(), .read); try T.expectError(error.BadUsage, acts.doAct(&rdo, .react, "Mom", "x", "👍")); var live = rg.ses(rig.cfgOf(), .live); try T.expectError(error.BadJob, acts.doAct(&live, .react, "", "x", "👍")); try T.expectError(error.BadJob, acts.doAct(&live, .react, "Mom", "", "👍")); try T.expectError(error.NoElem, acts.doAct(&live, .react, "Mom", "no such message", "👍")); try T.expectError(error.BadJob, acts.doAct(&live, .react, "Mom", "Dinner", "")); }
test "download one file message records the file name" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); _ = try rg.js("Z.chats[0].msgs.push(mk('them','file','report.pdf'));openChat(Z.chats[0]);'x'"); try T.expect(try acts.doAct(&ses, .down, "Mom", "report.pdf", "")); try T.expectEqualStrings("report.pdf", try rg.js("Z.st.downloads[0]")); }
test "mention: picks the member from the popup, sends the exact text; unknown names stay plain text" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); try T.expect(try snd.sendText(&ses, "Anna#group", "hello @Mom please call") == .sent); try T.expectEqualStrings("Anna|hello @Mom please call", try rg.js("Z.st.sent[0]")); ses.fake_ms += 600000; try T.expect(try snd.sendText(&ses, "Anna#group", "ping @Zzz now") == .sent); try T.expectEqualStrings("Anna|ping @Zzz now", try rg.js("Z.st.sent[1]")); try T.expectEqual(@as(?usize, 6), snd.mentionAt("hello @Mom", 0)); try T.expect(snd.mentionAt("mail a@b.c", 0) == null); try T.expect(snd.mentionAt("@", 0) == null); try T.expectEqualStrings("Mom", snd.mentionName("hi @Mom, ok", 3)); }
test "composer compare ignores outer space and non-breaking spaces" { try T.expect(snd.same(" a\xC2\xA0b \n", "a b")); try T.expect(!snd.same("a b", "a  b")); try T.expect(!snd.same("", "x")); }
